void record_key_event(uint32_t key,lv_obj_t * ui_Screen)
{
    ui_screen_record_obj_t * p_screen_param;

    p_screen_param      = (ui_screen_record_obj_t *) lv_obj_get_user_data(ui_Screen);

    switch (key)
    {
        case LV_KEY_UP:
            {

                }
            break;

        case LV_KEY_DOWN:
            {

                }
            break;

        case APP_KEY_VALUE_TOP_LEFT:
            {
                if (p_screen_param->handle_timer == NULL) {
                    alv_am_win_enter(NULL,"record_option",NULL);
                    }
                else {
                    if (p_screen_param->handle_timer->paused)
                        record_timer_resume(ui_Screen);
                    else 
                        record_timer_pause(ui_Screen);
                    }
                }
            break;

        case APP_KEY_VALUE_TOP_RIGHT:
            {
                if (p_screen_param->handle_timer == NULL) {
                    alv_am_win_exit_current(NULL);
                    }
                else {
                    record_storage_success_remind_screen(ui_Screen);
                    }

                }
            break;

        case LV_KEY_ENTER:
            {
                if (0 == sd_storage_space_is_enough()) {
                    create_comp_msgbox_remind_play_tts_menu("内存空间不足!");
                    break;
                    }

                if (p_screen_param->handle_timer == NULL) {
                    record_timer_start(ui_Screen);
                }else {
                    if(p_screen_param->handle_timer->paused)
                        record_timer_resume(ui_Screen);
                    else
                        record_timer_pause(ui_Screen);
                }

            }
            break;

        case LV_KEY_END:
            if (p_screen_param->handle_timer == NULL)
                alv_am_app_exit_action_all();

            break;
        }
}



