static void record_timer_event_cb(struct _lv_timer_t *timer)
{
    lv_obj_t *      ui_Screen;
    ui_screen_record_obj_t * p_screen_param;
    uint16_t        hour,min,second;
    uint32_t        time_cur,time_start,time_tmp;
    aos_systime     time;

    ui_Screen           = timer->user_data;
    p_screen_param      = (ui_screen_record_obj_t *) lv_obj_get_user_data(ui_Screen);

    aos_get_systime(&time);

    time_cur            = time.hour * 3600 + time.minute * 60 + time.second;
    time_start          =
         p_screen_param->time_start.hour * 3600 + p_screen_param->time_start.minute * 60 + p_screen_param->time_start.second;


    if (time_cur < time_start)
        time_tmp = time_cur + 24 * 3600 - time_start;
    else 
        time_tmp = time_cur - time_start;

    if (time_tmp == 0) {
        return;
        }
    else {
        p_screen_param->time_count = p_screen_param->time_count + time_tmp;
        time_tmp            = p_screen_param->time_count;
        memcpy(&p_screen_param->time_start,&time,sizeof(aos_systime));

        }

    if (0 == sd_storage_space_is_enough()) {
        create_comp_msgbox_remind_play_tts_menu("内存空间不足!");
        record_timer_stop(ui_Screen);
        backlight_turn_on();
        return;
        }

    if (RECROD_TIME_MAX <= time_tmp) {
        record_timer_stop(ui_Screen);
        backlight_turn_on();
        return;
        }



    hour                = time_tmp / 3600;
    min                 = time_tmp % 3600 / 60;
    second              = time_tmp % 3600 % 60;
    __inf("time_cur:%d,time_start:%d,time_tmp:%d,%d:%d:%d",time_cur,time_start,time_tmp,hour,min,second);

    sprintf(p_screen_param->str_time,"%02d:%02d:%02d",hour,min,second);
    lv_label_set_text(p_screen_param->obj_time1,p_screen_param->str_time);


    hour                = (RECROD_TIME_MAX - time_tmp) / 3600;
    min                 = (RECROD_TIME_MAX - time_tmp) % 3600 / 60;
    second              = (RECROD_TIME_MAX - time_tmp) % 3600 % 60;
    sprintf(p_screen_param->str_time,"%02d:%02d:%02d",hour,min,second);
    lv_label_set_text(p_screen_param->obj_time2,p_screen_param->str_time);



}


void record_timer_start(lv_obj_t * ui_Screen)
{
    ui_screen_record_obj_t * p_screen_param;

    p_screen_param      = (ui_screen_record_obj_t *) lv_obj_get_user_data(ui_Screen);

    if (p_screen_param->music_play_pre_status == 0) {
        p_screen_param->music_play_pre_status = app_musicplayer_get_play_status();
        }

    app_musicplayer_stop();

    if (p_screen_param->handle_timer == NULL) {
        p_screen_param->handle_timer = lv_timer_create(record_timer_event_cb,500,ui_Screen);
        p_screen_param->time_count = 0;
        aos_get_systime(&p_screen_param->time_start);
        }

    lv_img_set_src(p_screen_param->obj_img,ui_imgset_select[1]);
    lv_obj_add_flag(p_screen_param->obj_label[OBJ_LABEL_START],LV_OBJ_FLAG_HIDDEN);
    lv_label_set_text(p_screen_param->obj_label[OBJ_LABEL_SELELCT],"暂停");
    lv_label_set_text(p_screen_param->obj_label[OBJ_LABEL_BACK],"停止");

    app_recorder_resume("Rec");


}




